def longest_subseq_with_diff_one(arr, diff):
    n = len(arr)
    dp = [[0] * (diff + 1) for _ in range(n)]
    for i in range(n):
        dp[i][0] = 1
    for i in range(1, n):
        for j in range(1, diff + 1):
            if arr[i] == arr[i - 1]:
                dp[i][j] = dp[i - 1][j]
            else:
                dp[i][j] = dp[i - 1][j - 1] + 1
    return max(dp[n - 1])

