                product *= arr[k]
            if product > max_product:
                max_product = product
    return max_product

def max_profit(prices, k):
    if k == 0 or len(prices) == 0:
        return 0
    profit = 0
    for i in range(len(prices)):
        for j in range(i+1, len(prices)):
            profit = max(profit, prices[j] - prices[i])
    return profit

def add_pairwise(tuples):
