import re

def match(string):
    pattern = re.compile(r'[A-Z][a-z]+')
    return bool(pattern.search(string))

def first_Factorial_Divisible_Number(x):
    for i in range(1, x+1):
        if factorial(i) % x == 0:
            return i
    return None

def factorial(n):
    if n == 0:
        return 1
    else:
        return n * factorial(n-1)

def largest_palindrome(arr):
    largest = 0
    for num in arr:
        if is_palindrome(num):
            if num > largest:
                largest = num
    return largest

def is_palindrome(num):
    num_str = str(num)
    return num_str == num_str[::-1]

def binomial_probability(n, k, p):
    """
    Compute the binomial probability for the given number of trials, 
    the number of successes, and the probability of success on a single trial.
    """
    return (p**k) * ((1-p)**(n-k))

def frequency_Of_Largest(arr):
    max_val = max(arr)
    return arr.count(max_val)

def extract_symmetric(tuples):
    result = set()
    for i in range(len(tuples)):
        for j in range(i+1, len(tuples)):
            if tuples[i] == tuples[j]:
                result.add((tuples[i], tuples[j]))
    return result

def sum_gp(a, r, n):
    if n == 1:
        return a
    else:
        return a + r * sum_gp(a, r, n-1)

def binary_search(arr, x):
    low = 0
    high = len(arr) - 1
    while low <= high:
        mid = (low + high) // 2
        if arr[mid] == x:
            return mid
        elif arr[mid] < x:
            low = mid + 1
        else:
            high = mid - 1
    return -1

def calculate_polygons(x, y, width, height, num):
    polygons = []
    for i in range(num):
        polygon = []
        for j in range(num):
            polygon.append([x + (width * j), y + (height * i)])
        polygons.append(polygon)
    return polygons

