def heap_queue_smallest(numbers, k):
    # Create a min-heap
    heap = []
    for num in numbers:
        heapq.heappush(heap, num)
    # Get the k smallest numbers
    smallest = []
    for _ in range(k):
        smallest.append(heapq.heappop(heap))
    return smallest

def gcd(a, b):
