def re_order(arr):
    i = 0
    for j in range(len(arr)):
        if arr[j] != 0:
            arr[i] = arr[j]
            i += 1
    return arr

def permutation_coefficient(n, k):
    if k > n:
        return 0
    if k == 0 or k == n:
        return 1
    return permutation_coefficient(n-1, k-1) * n

def same_order(list1, list2):
    if len(list1) != len(list2):
        return False
    for i in range(len(list1)):
