            return False
    return True

def average_Odd(n):
    sum = 0
    for i in range(1, n+1, 2):
        sum += i
    return sum / n

def no_of_subsequences(arr, k):
    n = len(arr)
    dp = [[0 for _ in range(k+1)] for _ in range(n+1)]
    for i in range(n+1):
        for j in range(k+1):
            if i == 0 or j == 0:
                dp[i][j] = 0
            elif arr[i-1] <= j:
                dp[i][j] = dp[i-1][j] + dp[i-1][j-arr[i-1]]
            else:
                dp[i][j] = dp[i-1][j]
    return dp[n][k]
